function formatFileSize(bytes=0){return bytes<1024?`${bytes} B`:bytes<1048576?`${(bytes/1024).toFixed(1)} KB`:`${(bytes/1048576).toFixed(1)} MB`}
function openDocumentDatabase(){return new Promise((resolve,reject)=>{const request=indexedDB.open('nexo-documents',2);request.onupgradeneeded=()=>{const db=request.result;if(!db.objectStoreNames.contains('quotations'))db.createObjectStore('quotations',{keyPath:'orderId'});if(!db.objectStoreNames.contains('productMedia')){const store=db.createObjectStore('productMedia',{keyPath:'id'});store.createIndex('productId','productId',{unique:false})}if(!db.objectStoreNames.contains('movementEvidence')){const store=db.createObjectStore('movementEvidence',{keyPath:'id'});store.createIndex('movementId','movementId',{unique:false})}};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function storeQuotationDocument(orderId,file){const db=await openDocumentDatabase();return new Promise((resolve,reject)=>{const transaction=db.transaction('quotations','readwrite');transaction.objectStore('quotations').put({orderId,name:file.name,type:file.type,size:file.size,blob:file});transaction.oncomplete=()=>{db.close();resolve()};transaction.onerror=()=>{db.close();reject(transaction.error)}})}
async function storeMediaRecords(storeName,ownerField,ownerId,files){const records=[];for(const [index,file] of [...files].entries()){const hash=await fileFingerprint(await file.arrayBuffer()),id=`${ownerId}-${Date.now()}-${index}`;records.push({id,[ownerField]:ownerId,name:file.name,type:file.type||'application/octet-stream',size:file.size,hash,createdAt:new Date().toISOString(),blob:file})}if(!records.length)return records;const db=await openDocumentDatabase();return new Promise((resolve,reject)=>{const tx=db.transaction(storeName,'readwrite'),store=tx.objectStore(storeName);records.forEach(record=>store.put(record));tx.oncomplete=()=>{db.close();resolve(records)};tx.onerror=()=>{db.close();reject(tx.error)}})}
async function getMediaRecords(storeName,indexName,ownerId){const db=await openDocumentDatabase();return new Promise((resolve,reject)=>{const request=db.transaction(storeName,'readonly').objectStore(storeName).index(indexName).getAll(ownerId);request.onsuccess=()=>{db.close();resolve(request.result||[])};request.onerror=()=>{db.close();reject(request.error)}})}
window.BioMediaStore={store:(storeName,ownerField,ownerId,files)=>storeMediaRecords(storeName,ownerField,ownerId,files),get:(storeName,indexName,ownerId)=>getMediaRecords(storeName,indexName,ownerId)};
const validMediaFiles=(files,imagesOnly=false)=>{const incoming=[...files],selected=incoming.slice(0,5),allowed=imagesOnly?selected.every(file=>/^image\/(png|jpeg|webp)$/.test(file.type)):selected.every(file=>file.type==='application/pdf'||file.type.startsWith('image/'));return {files:selected,valid:incoming.length<=5&&allowed&&selected.every(file=>file.size<=5*1024*1024)}};
const productImageMarkup=product=>`<span class="product-image" data-product-thumbnail="${product.id}" style="background:${product.color}">${escapeHtml(product.name.slice(0,1))}</span>`;
let productMediaUrls=[];
async function hydrateProductImages(){productMediaUrls.forEach(url=>URL.revokeObjectURL(url));productMediaUrls=[];for(const product of products.filter(item=>item.images?.length)){const primary=product.images.find(image=>image.isPrimary)||product.images[0];try{const records=await getMediaRecords('productMedia','productId',product.id),record=records.find(item=>item.id===primary.id);if(!record)continue;const url=URL.createObjectURL(record.blob);productMediaUrls.push(url);document.querySelectorAll(`[data-product-thumbnail="${product.id}"]`).forEach(node=>{node.textContent='';node.style.backgroundImage=`url("${url}")`})}catch{}}}
async function downloadQuotationDocument(orderId){try{const db=await openDocumentDatabase(),record=await new Promise((resolve,reject)=>{const request=db.transaction('quotations','readonly').objectStore('quotations').get(orderId);request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});db.close();if(!record){showToast('El archivo de cotización no está disponible en este equipo.');return}const link=document.createElement('a');link.href=URL.createObjectURL(record.blob);link.download=record.name;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)}catch{showToast('No fue posible recuperar la cotización.') }}
movements.forEach(movementMeta);const removedLegacyPriceProducts=removeLegacyPriceListInventoryProducts();if(removedLegacyPriceProducts)movements.unshift(newMovement({type:'precio',title:'Corrección de catálogo de precios',detail:`${removedLegacyPriceProducts} artículo${removedLegacyPriceProducts===1?'':'s'} de lista se retiró${removedLegacyPriceProducts===1?'':'n'} del inventario; permanece disponible únicamente para cotizar.`,qty:`${removedLegacyPriceProducts} retirados de inventario`,time:'Ahora'}));save();
